"""Report actual probability recovery, controls, failures and descriptive split."""
import json,csv,importlib.util
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent
def read(p):return json.loads((R/p).read_text())
def load(n,p):
 s=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def avg(xs):return float(np.mean(xs))
def main():
 A=load('rescue_report_analysis',R/'rescue_analysis.py');A.main();analysis=read('rescue_analysis.json');rows=analysis['discovery']['rows'];records=A.collect('discovery');split=read('block27_component_aggregates.json');waves=read('block27_pulse_aggregates.json');uncertainty={};cells=[];permarker=[]
 for direction in ['empty<-assistant8','assistant8<-empty']:
  rs=[r for r in records if r['recipient']+'<-'+r['donor']==direction];mr=[r for r in rows if r['direction']==direction];new=8 if direction.startswith('empty') else 0;old=0 if new==8 else 8
  uncertainty[direction]={k:dict(mean=avg([r[k] for r in mr]),descriptive_passage_bootstrap95=A.boot([r[k] for r in mr],.95)) for k in ['rescue_new','gain_joint','joint_advantage_over_MLPonly','offphase_NLL_cost']}
  for cell in ['native','L24only','L27only','joint','donor_MLP_only','joint_donor_MLP','joint_recipient_MLP','joint_random0','joint_random1']:
   pr=[A.phase(r['cells'][cell],r['common_positions']) for r in rs];costs=[]
   for r in rs:
    cost=np.array(r['cells']['joint']['score']['content_logp'])-np.array(r['cells'][cell]['score']['content_logp']);mask=~np.isin(np.array(r['common_positions'])%16,[15,0,7,8]);costs.append(float(cost[mask].mean()))
    z=np.array(r['cells'][cell]['score']['centered_marker_logits']);partition=np.array(r['cells'][cell]['score']['centered_log_partition']);pos=np.array(r['common_positions'])%16
    for j,tok in enumerate([3554,30625]):permarker.append(dict(topic=r['topic'],direction=direction,cell=cell,token=tok,new_phase_probability=float(np.exp(z[pos==new,j]-partition[pos==new]).mean()),old_phase_probability=float(np.exp(z[pos==old,j]-partition[pos==old]).mean())))
   cells.append(dict(direction=direction,cell=cell,new_probability=avg([p[new] for p in pr]),old_probability=avg([p[old] for p in pr]),offphase_NLL_cost_vs_joint=avg(costs)))
 with (R/'rescue_both_markers.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(permarker[0]));w.writeheader();w.writerows(permarker)
 (R/'descriptive_uncertainty.json').write_text(json.dumps(uncertainty,indent=2));(R/'rescue_cell_means.json').write_text(json.dumps(cells,indent=2))
 text=['# Missing punctuation: actual-cell decomposition and one final-MLP rescue','', '**Outcome: partial actual punctuation recovery, but NOT a clean selective rescue. The frozen discovery gate failed; eight fresh validation passages remain untouched. No further rescue was run.**','', 'The previous joint L24/L27 attention-mixing intervention reversed the measured head timing coordinate on all four passages in both directions but left new-phase exact-marker probability near zero. This study asks what a native true punctuation tick has that the failed transported tick lacks. No new model training or behavioural objective search was performed.','', '## What was missing','', 'The saved same-cell allocation first showed that most of the missing marker score lay outside the selected learned L24/L27 output-column writes. A narrowly scoped32-forward replay split the actual final residual into: incoming residual before block27, full attention27 update, and MLP27 update. Their sum was checked against the actual final residual. Every component below uses its own counterfactual\'s ACTUAL final RMS gain; these are exact within-run logit allocations, not independent causal effects.','', '| Direction | Marker | Condition | Incoming residual | Attention27 | MLP27 | Final centered marker logit |','|---|---:|---|---:|---:|---:|---:|']
 for r in split:text.append(f"| {r['direction']} | {r['token']} | {r['condition']} | {r['incoming']:.3f} | {r['attention']:.3f} | {r['MLP']:.3f} | {r['total']:.3f} |")
 text+=['', 'For30625, the incoming residual is roughly10–11nat lower at failed new ticks, and the MLP supplies roughly8nat less. Full attention partly offsets this gap rather than explaining it all. For3554, the MLP can even oppose the marker. Thus there is no single universal ' + '“opposing remainder” or final punctuation blocker established by subtraction.','', 'These are means across heterogeneous ticks and passages. Mean logits must NOT be exponentiated to infer mean probabilities. Individual per-position values, both marker identities and content-relative component gaps are preserved in individual_true_tick_comparisons.csv and block27_components.csv.','', '### Amplitude, smooth timing, sharp pulse and DC','', 'Phase-average RAW marker-directed readouts (before final RMS scaling) can be algebraically split into DC, period16 fundamental, and higher harmonics. This is descriptive geometry only, not a new intervention on Fourier components. For MLP27 and30625 at the predetermined new tick:','', '| Direction | Condition | DC | Fundamental at tick | Higher harmonics at tick | Total raw readout |','|---|---|---:|---:|---:|---:|']
 for r in waves:
  if r['piece']=='MLP' and r['token']==30625:text.append(f"| {r['direction']} | {r['condition']} | {r['DC']:.3f} | {r['fundamental_at_new']:.3f} | {r['higher_at_new']:.3f} | {r['total_at_new']:.3f} |")
 text+=['', 'The missing MLP readout is not just a constant offset. Both its fundamental contribution at the requested tick and the sharper higher-harmonic contribution are weaker or wrongly phased. Reversing one selected attention-head coordinate did not reproduce this full downstream marker-producing waveform. The separate A5000 component-only study is not pooled here and is not replicated.','', '## Frozen causal rescue','', 'Intervention: replace ONLY the block27 MLP output UPDATE in the failed joint counterfactual with the native donor\'s update at corresponding causal query tokens. Apply at all aligned common queries1..127; query0 and other positions stay unchanged. Keep the recipient incoming residual, attention path, weights and current joint counterfactual; recompute final RMS and full-vocabulary softmax. This is not a final-logit injection or replacement of the complete final residual.','', 'The native donor has identical reference text and corresponding prior token identity, but the empty/assistant8 context shifts its true tick. This is a teacher-forced causal state intervention; it does not demonstrate the model autonomously moving a punctuation signal. A native+donor-MLP-only arm asks whether the late update works without the earlier attention swaps. Other controls are native-recipient MLP, self sham, and two per-token norm-matched random changes.','', 'Success required>=1% actual new-phase probability AND>=10%native donor peak,>=1percentage-point improvement over joint and each random control, dominance of the predicted new window over the old, and<=0.10nat/token off-clock reference NLL cost, in at least3/4passages in EACH direction. Native-recipient MLP control must not produce comparable recovery. All criteria were frozen before rescue outcomes.','', '## Actual results','', 'Forward means empty recipient receiving assistant8 donor (new common phase8). Reverse means assistant8 recipient receiving empty donor (new common phase0). Common positions are one-based modulo16. Values are arithmetic probability means.','', '| Direction | Arm | New-phase marker probability | Old-phase marker probability | Off-clock NLL cost versus joint |','|---|---|---:|---:|---:|']
 for r in cells:text.append(f"| {r['direction']} | {r['cell']} | {100*r['new_probability']:.6f}% | {100*r['old_probability']:.6f}% | {r['offphase_NLL_cost_vs_joint']:+.4f} |")
 text+=['', '### Every discovery case, including failures','', '| Passage | Direction | Native donor true peak | Failed joint new peak | MLP rescue new peak | Off-clock NLL cost | Full gate |','|---|---|---:|---:|---:|---:|---|']
 for r in rows:text.append(f"| {r['topic']} | {r['direction']} | {100*r['donor_peak']:.5f}% | {100*r['joint_new']:.7f}% | {100*r['rescue_new']:.5f}% | {r['offphase_NLL_cost']:+.4f} | {'PASS' if r['passed'] else 'FAIL'} |")
 text+=['', '**The transplant does create substantial actual new peaks in four of eight directional cases.** Random perturbations and native-recipient MLP do not reproduce those large peaks. But only unique_items forward passes every criterion. Strong film_projector forward, roll_length reverse and unique_items reverse results fail the off-clock NLL limit; remaining cases fail adequate amplitude/consistency. The gate is1/4forward and0/4reverse versus3/4required, so no confirmation was run.','', 'Native+donor MLP alone already yields11.30% and17.70% on film_projector/unique_items forward, and30.91% on unique_items reverse. Joint sometimes adds to that result, but the earlier phase swaps have not been shown necessary. This argues against calling the result proof of unique L24-to-L27 mediation.','', 'Reference loss is measured on the actual fixed reference tokens at identical histories. It is a prediction-quality control, not a standalone behavioural competence evaluation or a test of free-generation coherence. Off-clock damage cannot be explained solely by deliberately increasing punctuation at the selected ticks. All-position costs and both marker identities are retained.','', '## Causal verdict','', '- Supported on some discovery cases: the native donor\'s final MLP update can supply enough missing support to produce a real new punctuation-probability peak in these counterfactual histories. This is stronger than a Fourier phase reversal alone.','- Not established: a selective general rescue, upstream mediation through the measured timing component, one necessary blocker, or a complete naturally operating punctuation circuit. The incoming residual gap remains, and the output transplant changes a full MLP update.','- Not tested after the failed gate: independent held-out generalization, actual sampled punctuation emission, semantic/communication consequences, or another rescue of the incoming residual.','- No evidence from this test of collusion, intentional signalling or the competition\'s hidden objective.','', '## Uncertainty and stopping','', 'Four independent discovery passages per direction are exploratory. Descriptive passage-bootstrap95% intervals are in descriptive_uncertainty.json; no token is treated as an independent experiment. No corrected confirmation inference is claimed. The frozen8passage confirmation bank was not scored. No thresholds, directions or candidate components were adjusted after failure.','', '## Engineering and provenance','', 'Pinned Dolos63e7031a0535a49f86e08af4e7bdc45cfa22fe6d; Qwen989aa7980e4cf806f80c7fef2b1adb7bc71aa306. RTX4070Laptop, FP32, batch1, twoCPUthreads, TF32off. Narrow capture32forwards23.9seconds; rescue96forwards34.125seconds. Peak GPU allocation approximately6.38GB,80C thermal supervisor. All native scoring reproduced exactly in rescue; self-sham difference0; random norm relative error<=1.20e-7. Parameter hashes unchanged and both local GPU leases released. No training, BRC, paid compute, new pod or publication.','', 'Reproducible files: RESCUE_PROTOCOL.md, rescue_frozen_sources.json, rescue.py, rescue_analysis.py, rescue_metrics.csv, rescue_phase_profiles.csv, rescue_both_markers.csv, capture_results.json, block27_components.csv, block27_pulse_components.csv and final_verification.json. Prior experiments are unchanged.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axs=plt.subplots(1,2,figsize=(12,4.7),sharey=True)
 for ax,d in zip(axs,['empty<-assistant8','assistant8<-empty']):
  rs=[r for r in records if r['recipient']+'<-'+r['donor']==d]
  for cell in ['native','joint','donor_MLP_only','joint_donor_MLP','joint_recipient_MLP','joint_random0']:ax.plot(range(16),100*np.mean([A.phase(r['cells'][cell],r['common_positions']) for r in rs],0),marker='.',label=cell)
  ax.set(title=d,xlabel='One-based common position modulo16');ax.axvline(8 if d.startswith('empty') else 0,color='grey',alpha=.3);ax.legend(fontsize=7)
 axs[0].set_ylabel('Exact marker probability (%)');fig.tight_layout();fig.savefig(R/'rescue_phase_comparison.png',dpi=160);plt.close(fig)
if __name__=='__main__':main()
